\set ON_ERROR_STOP on
-- psql export commands; this file is not a DataGrip SQL script.
-- Docker mounts reports/ at /reports. Update output paths for a local psql client.
\copy (SELECT 'machines' AS metric, CAST(COUNT(*) AS TEXT) AS value FROM machines UNION ALL SELECT 'telemetry_rows', CAST(COUNT(*) AS TEXT) FROM telemetry UNION ALL SELECT 'error_rows', CAST(COUNT(*) AS TEXT) FROM errors UNION ALL SELECT 'maintenance_rows', CAST(COUNT(*) AS TEXT) FROM maintenance UNION ALL SELECT 'failure_rows', CAST(COUNT(*) AS TEXT) FROM failures UNION ALL SELECT 'telemetry_start', CAST(MIN(datetime) AS TEXT) FROM telemetry UNION ALL SELECT 'telemetry_end', CAST(MAX(datetime) AS TEXT) FROM telemetry UNION ALL SELECT 'maintenance_before_telemetry', CAST(COUNT(*) AS TEXT) FROM maintenance WHERE datetime < (SELECT MIN(datetime) FROM telemetry) UNION ALL SELECT 'off_grid_readings', CAST(COUNT(*) AS TEXT) FROM telemetry WHERE MOD(EXTRACT(EPOCH FROM (datetime - (SELECT MIN(datetime) FROM telemetry))), 3600) <> 0 UNION ALL SELECT 'machines_with_missing_hours', CAST(COUNT(*) AS TEXT) FROM (SELECT m.machine_id FROM machines m LEFT JOIN telemetry t ON t.machine_id = m.machine_id GROUP BY m.machine_id HAVING COUNT(t.datetime) <> (SELECT EXTRACT(EPOCH FROM (MAX(datetime) - MIN(datetime))) / 3600 + 1 FROM telemetry)) missing) TO '/reports/results/data_quality_summary.csv' WITH (FORMAT csv, HEADER true)
\copy (SELECT m.model, COUNT(DISTINCT m.machine_id) AS machine_count, COUNT(f.machine_id) AS failure_count, ROUND(COUNT(f.machine_id)::NUMERIC / NULLIF(COUNT(DISTINCT m.machine_id),0),3) AS failures_per_machine FROM machines m LEFT JOIN failures f ON f.machine_id = m.machine_id GROUP BY m.model ORDER BY failures_per_machine DESC, m.model) TO '/reports/results/model_failure_rates.csv' WITH (FORMAT csv, HEADER true)
\copy (SELECT component, COUNT(*) AS failure_count, ROUND(100.0 * COUNT(*) / NULLIF((SELECT COUNT(*) FROM failures),0),2) AS failure_pct FROM failures GROUP BY component ORDER BY failure_count DESC,component) TO '/reports/results/component_failure_share.csv' WITH (FORMAT csv, HEADER true)
\copy (SELECT (SELECT COUNT(*) FROM failures) AS component_failure_rows, (SELECT COUNT(*) FROM v_failure_events) AS distinct_failure_events, COUNT(*) AS complete_event_intervals, ROUND(AVG(EXTRACT(EPOCH FROM (datetime - previous_failure_ts))/3600.0),2) AS fleet_event_mtbf_hours, (SELECT COUNT(*) FROM machines m WHERE NOT EXISTS (SELECT 1 FROM failures f WHERE f.machine_id = m.machine_id)) AS failure_free_machines FROM v_failure_intervals WHERE previous_failure_ts IS NOT NULL) TO '/reports/results/reliability_summary.csv' WITH (FORMAT csv, HEADER true)
\copy (SELECT machine_id,complete_intervals,mtbf_hours FROM v_machine_mtbf ORDER BY machine_id) TO '/reports/results/machine_mtbf.csv' WITH (FORMAT csv, HEADER true)
\copy (SELECT m.model, SUM(x.maintenance_count) AS maintenance_count, SUM(x.reactive_count) AS reactive_count, ROUND(1.0*SUM(x.reactive_count)/NULLIF(SUM(x.maintenance_count),0),4) AS reactive_ratio FROM v_machine_maintenance x JOIN machines m ON m.machine_id=x.machine_id GROUP BY m.model ORDER BY m.model) TO '/reports/results/maintenance_reactive_rates.csv' WITH (FORMAT csv, HEADER true)
\copy (SELECT previous_change_type,COUNT(*) AS observed_failures,ROUND(AVG(component_age_days),2) AS average_days_to_failure FROM v_component_ages WHERE previous_change_ts IS NOT NULL GROUP BY previous_change_type ORDER BY previous_change_type) TO '/reports/results/maintenance_observed_component_age.csv' WITH (FORMAT csv, HEADER true)
\copy (SELECT COUNT(CASE WHEN e.datetime < f.datetime THEN 1 END) AS strict_leading_error_count, COUNT(e.error_id) AS inclusive_error_count, COUNT(CASE WHEN e.datetime = f.datetime THEN 1 END) AS same_timestamp_difference FROM failures f LEFT JOIN errors e ON e.machine_id=f.machine_id AND e.datetime >= f.datetime - INTERVAL '24 hours' AND e.datetime <= f.datetime) TO '/reports/results/error_window_sensitivity.csv' WITH (FORMAT csv, HEADER true)
\copy (SELECT component,error_id,pre_failure_errors_per_day,baseline_errors_per_machine_day,lift FROM v_error_lift ORDER BY lift DESC,component,error_id LIMIT 10) TO '/reports/results/error_lift_top10.csv' WITH (FORMAT csv, HEADER true)
\copy (SELECT component,failures_with_telemetry,volt_change_pct,rotate_change_pct,pressure_change_pct,vibration_change_pct FROM v_sensor_changes ORDER BY component) TO '/reports/results/telemetry_pre_failure_percentage_changes.csv' WITH (FORMAT csv, HEADER true)
\copy (SELECT machine_id,model,age,n_failures,mtbf_hours,reactive_ratio,errors_per_day,priority_score,CASE WHEN priority_score >= 15 THEN 'high' WHEN priority_score >= 10 THEN 'medium' ELSE 'low' END AS maintenance_priority FROM v_machine_kpi ORDER BY priority_score DESC,machine_id LIMIT 10) TO '/reports/results/top_maintenance_priorities.csv' WITH (FORMAT csv, HEADER true)
\copy (SELECT COUNT(*) AS machines_in_view,SUM(n_failures) AS view_failure_sum,(SELECT COUNT(*) FROM failures) AS source_failure_count FROM v_machine_kpi) TO '/reports/results/kpi_grain_validation.csv' WITH (FORMAT csv, HEADER true)
